import React, { useState } from "react";
import { useLocation } from "react-router-dom";
import "./Questionnaire.css";

function BudgetLimits() {
  const location = useLocation();
  const categories = location.state?.categories || [];

  const [limits, setLimits] = useState({});

  const handleChange = (cat, value) => {
    setLimits((prev) => ({
      ...prev,
      [cat]: value
    }));
  };

  const handleSave = () => {
    alert("Budget limits saved successfully!");
    console.log("Saved Limits:", limits);
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">

        <h2 className="questionnaire-title">
          Set Monthly Budget Limits
        </h2>

        {categories.length === 0 && (
          <p style={{ textAlign: "center" }}>
            No categories selected with priority ≥ 3
          </p>
        )}

        {categories.map((cat) => (
          <div className="form-group" key={cat}>
            <label className="form-label">{cat}</label>
            <input
              type="number"
              className="form-input"
              placeholder="Enter amount"
              value={limits[cat] || ""}
              onChange={(e) => handleChange(cat, e.target.value)}
            />
          </div>
        ))}

        {categories.length > 0 && (
          <button className="next-button" onClick={handleSave}>
            Save Limits
          </button>
        )}

      </div>
    </div>
  );
}

export default BudgetLimits;
